package com.clothingstore;
import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/auth") @CrossOrigin(origins="${app.cors-origin}") public class AuthController { private final UserAccountRepository users; private final PasswordEncoder encoder; private final JwtService jwt; AuthController(UserAccountRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;} record RegisterRequest(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=8) String password){} record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} record AuthResponse(String token,String role,String name){} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) AuthResponse register(@RequestBody @jakarta.validation.Valid RegisterRequest body){if(users.existsByEmail(body.email().toLowerCase()))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account already exists for this email.");UserAccount user=new UserAccount();user.setFullName(body.fullName());user.setEmail(body.email());user.setPasswordHash(encoder.encode(body.password()));user.setRole("CUSTOMER");users.save(user);return new AuthResponse(jwt.create(user),user.getRole(),user.getFullName());} @PostMapping("/login") AuthResponse login(@RequestBody @jakarta.validation.Valid LoginRequest body){UserAccount user=users.findByEmail(body.email().toLowerCase()).filter(UserAccount::isEnabled).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password."));if(!encoder.matches(body.password(),user.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password.");return new AuthResponse(jwt.create(user),user.getRole(),user.getFullName());} }
